package sanitize_test

import (
	"strings"
	"testing"

	"github.com/Sahas001/readit/internal/sanitize"
)

func BenchmarkSanitizeText_Short(b *testing.B) {
	input := "Hello world! This is a simple forum title with ANSI \x1b[31mred\x1b[0m text."
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_ = sanitize.Text(input)
	}
}

func BenchmarkSanitizeText_Long(b *testing.B) {
	input := strings.Repeat("Lorem ipsum dolor sit amet, consectetur adipiscing elit. \x1b[32mHighlighted\x1b[0m\n", 100)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		_ = sanitize.Text(input)
	}
}
